"""Lean integration contract (spec §37): proof generation is separate from acceptance.

Comparator pattern:
  * GenesisSpec.lean  — TRUSTED. Generated by this module from validated data
    (definitions and the `Statement` proposition). Untrusted code cannot edit it.
  * GenesisProof.lean — UNTRUSTED. Produced by a worker; must prove
    `GenesisSpec.Statement` as `GenesisProof.proof`, importing only GenesisSpec.
  * GenesisCheck.lean — TRUSTED. Imports both, checks
    `example : GenesisSpec.Statement := GenesisProof.proof`, and prints the
    axioms of the proof with a per-run nonce.
  * leanchecker replays every declaration of GenesisProof through the kernel.

Everything runs in the OCI sandbox (no network, read-only pinned toolchain at
/opt/lean), because Lean elaboration can execute arbitrary code. Outcomes are
kept distinct: CHECKED, ELABORATION_ERROR, KERNEL_REJECTED, STATEMENT_MISMATCH,
DISALLOWED_AXIOM, FORBIDDEN_CONSTRUCT, TIMEOUT, RESOURCE_LIMIT, CHECKER_ERROR.
"""
import re
import secrets
from pathlib import Path

from ..common import bytes_hash, digest
from ..graphs import check_witness
from .. import sandbox
from .tools import tool, ToolUnavailable

ALLOWED_AXIOMS = frozenset({'propext', 'Classical.choice', 'Quot.sound'})
FORBIDDEN = [r'\bsorry\b', r'\badmit\b', r'(?m)^\s*(?:private\s+|protected\s+)?axiom\b', r'\bunsafe\b',
             r'\bimplemented_by\b', r'@\[\s*extern', r'\bnative_decide\b', r'\bofReduceBool\b', r'\bofReduceNat\b',
             r'skipKernelTC', r'\brun_cmd\b', r'\brun_elab\b', r'\brun_meta\b', r'#eval\b', r'#exit\b',
             r'\binitialize\b', r'(?m)^\s*elab\b', r'(?m)^\s*macro(?:_rules)?\b', r'(?m)^\s*syntax\b',
             r'\baddDecl\b', r'\bdebug\.', r'\bLean\.Elab\b', r'\bIO\b', r'@\[\s*init', r'\bbuiltin_\w+',
             r'\bregister_\w+', r'\bLean\.Meta\b', r'\bopen\s+Lean\b', r'\bSystem\.', r'\bunsafeCast\b',
             r'\bcompile_inductive\b', r'\bdeclare_\w+', r'#print\b', r'#check_failure\b', r'\binclude_str\b']
LEAN_POLICY = sandbox.SandboxPolicy(wall_seconds=300, cpu_seconds=240, memory_mib=6144, pids=64, work_mib=256,
                                    tmp_mib=64, output_bytes=8 * 1024 * 1024, max_file_mib=128,
                                    open_files=16384, address_space_mib=262144)
SPEC_SCRIPT = '''set -u
cd /work/src && lean --root=/work/src -o /work/out/GenesisSpec.olean GenesisSpec.lean > /work/out/spec.log 2>&1 || exit 41
'''
PROOF_SCRIPT = '''set -u
cd /work/src && lean --root=/work/src -o /work/out/GenesisProof.olean GenesisProof.lean > /work/out/proof.log 2>&1 || exit 42
'''
CHECK_SCRIPT = '''set -u
cd /work/src
lean --root=/work/src GenesisCheck.lean > /work/out/check.log 2>&1 || exit 43
leanchecker GenesisProof > /work/out/leanchecker.log 2>&1 || exit 44
'''


def environment():
    """Identity of the pinned Lean toolchain used for checking (spec §37.2)."""
    lean = tool('lean')
    root = Path(lean['path']).parents[1]
    checker = root / 'bin' / 'leanchecker'
    return {'lean': lean['identity'], 'lean_sha256': lean['sha256'], 'version': lean['version'],
            'commit': lean['commit'], 'leanchecker_sha256': bytes_hash(checker.read_bytes()),
            'toolchain_root': str(root), 'allowed_axioms': sorted(ALLOWED_AXIOMS),
            'forbidden_patterns_sha256': digest(FORBIDDEN)}


def witness_spec(task, witness):
    """Trusted spec: the validated witness is simple, forbidden-motif-free and has k edges."""
    checked = check_witness(task, witness)
    literal = '[' + ', '.join(f'({u}, {v})' for u, v in checked['selected']) + ']'
    n, k = task.n, checked['value']
    pred = 'c4Free' if task.domain == 'c4_host_v2' else 'triangleFree'
    host = '[' + ', '.join(f'({u}, {v})' for u, v in task.edges) + ']'
    lines = [
        'namespace GenesisSpec',
        f'def host : List (Nat × Nat) := {host}',
        f'def witness : List (Nat × Nat) := {literal}',
        'def adj (u v : Nat) : Bool := witness.contains (min u v, max u v)',
        f'def vertices : List Nat := List.range {n}',
        f'def simple : Bool := witness.all (fun e => decide (e.1 < e.2) && decide (e.2 < {n}))',
        'def inHost : Bool := witness.all (fun e => host.contains e)',
        'def triangleFree : Bool := vertices.all (fun a => vertices.all (fun b => vertices.all (fun c =>',
        '  !(adj a b && adj b c && adj c a))))',
        'def c4Free : Bool := vertices.all (fun a => vertices.all (fun b => vertices.all (fun c => vertices.all (fun d =>',
        '  !((a != b && a != c && a != d && b != c && b != d && c != d) &&',
        '    adj a b && adj b c && adj c d && adj d a)))))',
        f'def Statement : Prop := simple = true ∧ inHost = true ∧ {pred} = true ∧ witness.length = {k}',
        'end GenesisSpec', '']
    statement = f'witness of {k} edges in host {digest(task.model_dump(mode="json"))[:16]} is simple, ' \
                f'inside the host and {pred}'
    return '\n'.join(lines).encode(), {'statement': statement, 'value': k, 'predicate': pred,
                                      'scope': 'finite witness predicate and cardinality; no optimum theorem'}


def default_proof():
    """What an honest worker submits for finite obligations (spec §37.1)."""
    return ('import GenesisSpec\nnamespace GenesisProof\n'
            'theorem proof : GenesisSpec.Statement := by\n  unfold GenesisSpec.Statement\n  decide\n'
            'end GenesisProof\n').encode()


def prescreen(proof_source):
    text = proof_source.decode('utf-8', errors='strict')
    imports = re.findall(r'(?m)^\s*import\s+(\S+)', text)
    if any(name != 'GenesisSpec' for name in imports):
        return f'disallowed import {sorted(set(imports) - {"GenesisSpec"})}'
    for pattern in FORBIDDEN:
        m = re.search(pattern, text)
        if m:
            return f'forbidden construct {m.group(0).strip()!r}'
    if 'theorem proof' not in text and 'def proof' not in text:
        return 'no GenesisProof.proof declaration'
    return None


def _check_source(nonce, done):
    return (f'import Lean\nimport GenesisSpec\nimport GenesisProof\nopen Lean in\n'
            f'#eval show CoreM Unit from do\n'
            f'  let axs ← Lean.collectAxioms ``GenesisProof.proof\n'
            f'  IO.println s!"GENESIS-{nonce} axioms {{axs.toList}}"\n'
            f'example : GenesisSpec.Statement := GenesisProof.proof\n'
            f'#eval IO.println "GENESIS-{done} statement-checked"\n').encode()


def _stage(files, script, env, policy):
    receipt = sandbox.run({**files, 'stage.sh': script.encode()}, ['/bin/sh', '/work/src/stage.sh'], policy,
                          ro_mounts={'/opt/lean': env['toolchain_root']},
                          env={'PATH_PREFIX': ['/opt/lean/bin'], 'LEAN_PATH': '/work/src:/opt/lean/lib/lean'})
    return receipt, receipt.get('_output_bytes', {})


def _artifacts(outputs, stem):
    return {name: data for name, data in outputs.items() if name.startswith(stem + '.') and 'log' not in name}


def check(spec_source, proof_source, *, policy=LEAN_POLICY):
    """Check an untrusted proof of a trusted spec in three isolated sandbox runs.

    1. compile the trusted spec (no untrusted input present);
    2. compile the untrusted proof against the spec's compiled files, mounted read-only;
    3. in a fresh sandbox holding only trusted sources and the two compiled modules,
       check the proof's type against the spec, audit axioms and replay with leanchecker.
    Untrusted elaboration-time code (if any slipped past the prescreen) never shares a
    writable directory with the trusted stages.
    """
    try:
        env = environment()
    except ToolUnavailable as exc:
        return {'status': 'CHECKER_ERROR', 'reason': str(exc)}
    base = {'schema': 'genesis-lean-receipt-v2', 'environment': env,
            'spec_sha256': bytes_hash(spec_source), 'proof_sha256': bytes_hash(proof_source)}
    problem = prescreen(proof_source)
    if problem:
        return dict(base, status='FORBIDDEN_CONSTRUCT', reason=problem)
    stages = {}

    def fail(receipt, name, logs):
        status = receipt['status']
        common = dict(base, stages=stages, logs={k: v[-4000:] for k, v in logs.items() if v})
        if status == 'TIMEOUT':
            return dict(common, status='TIMEOUT')
        if status in ('OOM', 'CPU_LIMIT', 'OUTPUT_LIMIT'):
            return dict(common, status='RESOURCE_LIMIT')
        if status in ('SANDBOX_UNAVAILABLE', 'SANDBOX_ERROR'):
            return dict(common, status='CHECKER_ERROR', reason=receipt.get('reason'))
        return None

    r1, o1 = _stage({'GenesisSpec.lean': spec_source}, SPEC_SCRIPT, env, policy)
    stages['spec'] = {'status': r1['status'], 'exit_code': r1.get('exit_code'), 'wall_ns': r1.get('wall_ns')}
    logs = {'spec.log': o1.get('spec.log', b'').decode(errors='replace')}
    early = fail(r1, 'spec', logs)
    if early:
        return early
    spec_files = _artifacts(o1, 'GenesisSpec')
    if r1.get('exit_code') != 0 or 'GenesisSpec.olean' not in spec_files:
        return dict(base, stages=stages, logs=logs, status='CHECKER_ERROR', reason='trusted spec failed to elaborate')
    spec_hashes = {k: bytes_hash(v) for k, v in spec_files.items()}

    r2, o2 = _stage({**spec_files, 'GenesisProof.lean': proof_source}, PROOF_SCRIPT, env, policy)
    stages['proof'] = {'status': r2['status'], 'exit_code': r2.get('exit_code'), 'wall_ns': r2.get('wall_ns')}
    logs['proof.log'] = o2.get('proof.log', b'').decode(errors='replace')
    early = fail(r2, 'proof', logs)
    if early:
        return early
    proof_files = _artifacts(o2, 'GenesisProof')
    if r2.get('exit_code') != 0 or 'GenesisProof.olean' not in proof_files:
        log = logs['proof.log']
        common = dict(base, stages=stages, logs={k: v[-4000:] for k, v in logs.items() if v})
        if '(kernel)' in log:
            return dict(common, status='KERNEL_REJECTED')
        if 'heartbeats' in log or 'maximum recursion' in log or 'deterministic timeout' in log:
            return dict(common, status='RESOURCE_LIMIT')
        return dict(common, status='ELABORATION_ERROR')

    nonce, done = secrets.token_hex(12), secrets.token_hex(12)
    r3, o3 = _stage({**spec_files, **proof_files, 'GenesisCheck.lean': _check_source(nonce, done)}, CHECK_SCRIPT,
                    env, policy)
    stages['check'] = {'status': r3['status'], 'exit_code': r3.get('exit_code'), 'wall_ns': r3.get('wall_ns'),
                       'peak_memory_bytes': r3.get('peak_memory_bytes')}
    logs['check.log'] = o3.get('check.log', b'').decode(errors='replace')
    logs['leanchecker.log'] = o3.get('leanchecker.log', b'').decode(errors='replace')
    early = fail(r3, 'check', logs)
    if early:
        return early
    out = dict(base, stages=stages, logs={k: v[-4000:] for k, v in logs.items() if v},
               spec_olean_sha256=spec_hashes, proof_olean_sha256={k: bytes_hash(v) for k, v in proof_files.items()},
               wall_ns=sum(st.get('wall_ns') or 0 for st in stages.values()))
    code = r3.get('exit_code')
    if code == 43:
        log = logs['check.log']
        if 'type mismatch' in log or 'Type mismatch' in log:
            return dict(out, status='STATEMENT_MISMATCH')
        return dict(out, status='CHECKER_ERROR', reason='trusted check failed')
    if code == 44:
        return dict(out, status='KERNEL_REJECTED', reason='leanchecker replay failed')
    if code != 0:
        return dict(out, status='CHECKER_ERROR', reason=f'unexpected exit {code}')
    check_lines = logs['check.log'].splitlines()
    lines = [l for l in check_lines if l.startswith(f'GENESIS-{nonce} axioms ')]
    if len(lines) != 1 or check_lines.count(f'GENESIS-{done} statement-checked') != 1:
        return dict(out, status='CHECKER_ERROR', reason='axiom report or completion marker missing or duplicated')
    listed = lines[0].split(' axioms ', 1)[1].strip()
    axioms = sorted(a.strip() for a in listed.strip('[]').split(',') if a.strip())
    out['axioms'] = axioms
    bad = sorted(set(axioms) - ALLOWED_AXIOMS)
    if bad:
        return dict(out, status='DISALLOWED_AXIOM', disallowed=bad)
    return dict(out, status='CHECKED', theorem='GenesisProof.proof : GenesisSpec.Statement')


def check_witness_formally(task, witness, proof_source=None):
    """Generate the trusted spec for a witness and check a (default) proof of it."""
    spec, meta = witness_spec(task, witness)
    receipt = check(spec, proof_source or default_proof())
    return dict(receipt, obligation=meta, task_sha256=digest(task.model_dump(mode='json')))
